def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.2)
        return float(max(0.0, safe_bid))

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) > 300:
            if bid is not None and float(bid) >= 75:
                rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # In this scenario supply 15-25 means only one agent can be fully satisfied each day.
    # Use yesterday pressure and our urgency to choose whether to contest.
    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    pressure = 0
    if highest_prev >= 110:
        pressure += 3
    elif highest_prev >= 85:
        pressure += 2
    elif highest_prev >= 60:
        pressure += 1

    pressure += min(2, desperate_count)
    pressure += min(1, rich_aggressive)

    # Budget-aware ceilings
    if budget < 40:
        return float(max(0.0, budget))

    # Emergency survival: secure water now.
    if urgency >= 5:
        bid = max(92.0, highest_prev + 4.0)
        bid = min(budget, bid)
        return float(max(0.0, bid))

    # High pressure but not desperate: avoid waste unless moderately urgent.
    if pressure >= 4 and urgency <= 1:
        bid = min(budget, 18.0)
        return float(max(0.0, bid))

    if pressure >= 4:
        bid = max(88.0, highest_prev + 2.5)
        bid = min(budget, bid)
        return float(max(0.0, bid))

    # Moderate pressure: selective contesting.
    if pressure >= 2:
        if urgency >= 3:
            bid = max(72.0, avg_prev + 3.0)
        elif urgency >= 2:
            bid = max(58.0, avg_prev * 0.9)
        else:
            bid = 28.0
        bid = min(budget, bid)
        return float(max(0.0, bid))

    # Low pressure: conserve against Bob/Cindy overbidding tendencies.
    if urgency >= 3:
        bid = 61.0
    elif urgency >= 2:
        bid = 42.0
    else:
        bid = 16.0 + (day % 3)

    # Slight upward adjustment if multiple opponents look weak and may suddenly contest.
    if desperate_count >= 2 and urgency >= 2:
        bid += 6.0

    bid = min(budget, bid)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents only
    alive_ids = []
    for agent_id, st in opponents_status.items():
        if st.get('alive', False):
            alive_ids.append(agent_id)

    # If no opponents alive, conserve
    if not alive_ids:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = {}
    for agent_id in alive_ids:
        prev = opponents_status[agent_id].get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
            prev_hp_after[agent_id] = prev.get('hp_after', None)

    # Identify likely pressure leader: highest yesterday bid
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Also check if Cindy was the main survivor with high budget
    cindy_prev_bid = None
    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive', False):
        prev = opponents_status['Cindy'].get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            cindy_prev_bid = float(prev['bid'])

    # Supply pressure: more supply means we can bid less to still secure water
    # Normalize supply to [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Urgency: if we are already in no-water streak or low hp, we must secure water
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    if no_water_days >= 1:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.6
    if my_hp <= 3.0:
        urgency += 0.4

    # Target bid baseline based on yesterday leader
    # If Cindy likely sets the pace (~85), we match slightly below/around it depending on urgency.
    leader_bid = highest_prev_bid
    if cindy_prev_bid is not None:
        # Prefer Cindy if she was strong survivor yesterday
        leader_bid = max(leader_bid, cindy_prev_bid)

    # Convert leader bid into a competitive bid
    # - If leader was very high, we raise only when urgency is high.
    # - Otherwise, we try to undercut to save budget.
    if leader_bid >= DAILY_SALARY * 0.85:
        if urgency >= 1.2:
            target = leader_bid * 0.98  # almost match
        elif urgency >= 0.6:
            target = leader_bid * 0.88  # likely enough
        else:
            target = leader_bid * 0.72  # conserve
    else:
        if urgency >= 1.2:
            target = max(DAILY_SALARY * 0.55, leader_bid + 5.0)
        elif urgency >= 0.6:
            target = max(DAILY_SALARY * 0.45, leader_bid + 2.5)
        else:
            target = max(DAILY_SALARY * 0.35, leader_bid * 0.75)

    # Adjust for supply: with higher supply, reduce bid; with lower supply, increase slightly
    # supply_norm high => cheaper
    target *= (1.10 - 0.25 * supply_norm)

    # Cap bid to avoid bankruptcy; also ensure not exceeding budget
    # If budget is low, bid more aggressively relative to remaining budget.
    if my_budget <= DAILY_SALARY * 0.6:
        budget_pressure = 1.0
    elif my_budget <= DAILY_SALARY * 1.2:
        budget_pressure = 0.8
    else:
        budget_pressure = 0.65

    target *= budget_pressure

    # Final clamp
    if target < 0.0:
        target = 0.0
    if target > my_budget:
        target = my_budget

    # If urgency is extreme, ensure a minimum competitive bid
    if urgency >= 1.2:
        min_competitive = DAILY_SALARY * 0.75
        if target < min_competitive:
            target = min(min_competitive, my_budget)

    # If we are doing fine, keep bids moderate
    if my_hp >= 6.0 and urgency < 0.6:
        target = min(target, DAILY_SALARY * 0.55)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    num_winners = int(supply // WATER_REQ)
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    estimated_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bid = trace['bid']
            prev_hp_after = trace.get('hp_after', opp['hp'])
            current_hp = opp['hp']
            if current_hp < prev_hp_after:
                factor = 1.2
            elif current_hp > prev_hp_after:
                factor = 0.9
            else:
                factor = 1.0
            est_bid = min(prev_bid * factor, opp['budget'])
        else:
            est_bid = 70.0
        estimated_bids.append(est_bid)
    estimated_bids.sort(reverse=True)
    if num_winners > 0 and len(estimated_bids) >= num_winners:
        threshold = estimated_bids[num_winners - 1]
    else:
        threshold = 0.0
    if my_hp <= 2:
        desired_bid = min(my_budget, DAILY_SALARY * 0.95)
    elif my_hp <= 5:
        desired_bid = min(my_budget, max(threshold + 0.5, DAILY_SALARY * 0.5))
    else:
        desired_bid = min(my_budget, max(threshold + 0.5, DAILY_SALARY * 0.3))
    return max(0.0, desired_bid)
